import { ShoppingCart, Menu, ShieldCheck, Phone } from 'lucide-react';
import { useApp } from '../contexts/AppContext';
import { BRAND } from '../lib/api';

export function Layout(){const {cart,user}=useApp();return <><header className="sticky top-0 z-50 glass border-b border-gray-200"><div className="containerx h-20 flex items-center justify-between"><Link to="/" className="flex items-center gap-3"><img src="/assets/logo-icon.png" alt="Gráfica W Criações" className="w-12 h-12 object-contain"/><span className="font-display text-xl md:text-2xl font-extrabold text-primary">Gráfica <span className="gold-text">W Criações</span></span></Link><nav className="hidden md:flex gap-6 font-semibold text-sm"><NavLink to="/catalogo">Catálogo</NavLink><NavLink to="/acompanhar">Acompanhar</NavLink><NavLink to="/sobre">Sobre</NavLink><NavLink to="/contato">Contato</NavLink>{user?.role==='admin'&&<NavLink to="/admin" className="text-accent">Admin</NavLink>}</nav><div className="flex items-center gap-3"><a href="https://wa.me/5588996240470" target="_blank" className="hidden lg:flex text-sm font-bold items-center gap-1"><Phone size={16}/>{BRAND.whatsapp}</a><Link to="/login" className="hidden sm:flex text-sm font-bold items-center gap-1"><ShieldCheck size={16}/>{user?user.nome:'Entrar'}</Link><Link to="/carrinho" className="relative btn btn-dark py-3"><ShoppingCart size={18}/>{cart.length>0&&<span className="absolute -top-2 -right-2 bg-accent text-primary rounded-full text-xs w-6 h-6 grid place-items-center font-extrabold">{cart.length}</span>}</Link><Menu className="md:hidden"/></div></div></header><main><Outlet/></main><footer className="bg-primary text-white mt-20"><div className="containerx py-12 grid md:grid-cols-4 gap-8"><div><img src="/assets/logo-wide.jpeg" alt="Gráfica W Criações" className="rounded-2xl max-w-[220px]"/><p className="text-gray-300 mt-3">Impressos, brindes e personalizados com padrão premium.</p></div><div><b>Loja</b><p className="text-gray-300 mt-3">Catálogo<br/>Carrinho<br/>Finalização pelo WhatsApp</p></div><div><b>Atendimento</b><p className="text-gray-300 mt-3">WhatsApp: {BRAND.whatsapp}<br/>Pedidos personalizados<br/>Orçamentos</p></div><div><b>Legal</b><p className="text-gray-300 mt-3">Privacidade<br/>Termos<br/>Recibos de pedido</p></div></div></footer></>}
